   383  otError Message::Append(const void *aBuf, uint16_t aLength)
   384  {
   385      otError  error     = OT_ERROR_NONE;
   386      uint16_t oldLength = GetLength();
   387      int      bytesWritten;
   388
   389      SuccessOrExit(error = SetLength(GetLength() + aLength));
   390      bytesWritten = Write(oldLength, aLength, aBuf);
   391
   392      assert(bytesWritten == (int)aLength);
   393      OT_UNUSED_VARIABLE(bytesWritten);
   394
   395  exit:
   396      return error;
